SELECT ?item ?en ?sv ?type ?partOf ?follows ?followedBy ?start WHERE {
  VALUES ?en { "Hadean"@en "Archean"@en "Proterozoic"@en "Phanerozoic"@en "Paleozoic"@en "Mesozoic"@en "Cenozoic"@en "Cambrian"@en "Ordovician"@en "Silurian"@en "Devonian"@en "Carboniferous"@en "Permian"@en "Triassic"@en "Jurassic"@en "Cretaceous"@en "Paleogene"@en "Neogene"@en "Quaternary"@en }
  ?item rdfs:label ?en .
  ?item wdt:P31 ?type .
  OPTIONAL { ?item rdfs:label ?sv FILTER(LANG(?sv) = "sv") }
  OPTIONAL { ?item wdt:P361 ?partOf }
  OPTIONAL { ?item wdt:P155 ?follows }
  OPTIONAL { ?item wdt:P156 ?followedBy }
  OPTIONAL { ?item wdt:P580 ?start }
}

SELECT ?item ?kind ?lang ?text WHERE {
  VALUES ?item { wd:Q104460 wd:Q104168 wd:Q104162 wd:Q101313 wd:Q75507 wd:Q83222 wd:Q102416 wd:Q79064 wd:Q62100 wd:Q62412 wd:Q65955 wd:Q133738 wd:Q76402 wd:Q47158 wd:Q45805 wd:Q44626 wd:Q55810 wd:Q103924 wd:Q26185 wd:Q103910 wd:Q43521 wd:Q63463770 wd:Q2669627 wd:Q2464485 wd:Q392928 }
  { ?item rdfs:label ?text . BIND("label" AS ?kind) }
  UNION { ?item skos:altLabel ?text . BIND("alias" AS ?kind) }
  BIND(LANG(?text) AS ?lang)
  FILTER(?lang IN ("en", "sv", "mul"))
}
ORDER BY ?item ?lang ?kind

SELECT ?item ?en ?sv ?partOf WHERE {
  VALUES ?item { wd:Q191935 wd:Q188654 }
  OPTIONAL { ?item rdfs:label ?en FILTER(LANG(?en) = "en") }
  OPTIONAL { ?item rdfs:label ?sv FILTER(LANG(?sv) = "sv") }
  OPTIONAL { ?item wdt:P361 ?partOf }
}
